def compute(vars):
    goodwill = vars["v1"]
    estimated_purchase_price = vars["v2"]

    if estimated_purchase_price == 0:
        return None

    percentage = goodwill / estimated_purchase_price * 100
    return {
        "value": percentage,
        "trace": {
            "goodwill": goodwill,
            "estimated_purchase_price": estimated_purchase_price,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
